&lt;p&gt;&lt;strong&gt;Role Summary:&lt;/strong&gt;&lt;/p&gt;
&lt;p data-ccp-border-bottom=&quot;0px none #000000&quot; data-ccp-padding-bottom=&quot;0px&quot; data-ccp-border-between=&quot;0px none #000000&quot; data-ccp-padding-between=&quot;0px&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;The Director, Medical Writing provides strategic leadership and hands-on execution&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; for the &lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;development&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; of high&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;-&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;quality, compliant clinical and regulatory documents &lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;supporting one or more development programs. This role partners closely with Clinical Development, Clinical Operations, Clinical Pharmacology, Regulatory Affairs, Research, Preclinical, Translational Biomarkers, Program Management, and Medical Affairs to ensure clear, consistent scientific messaging across key submissions to the FDA and global health authorities. Operating with a high degree of independence, the Director drives document planning, authoring, review, and finalization in alignment with company priorities, SOPs, ICH/GCP guidance, and applicable regulatory requirements.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p data-ccp-border-bottom=&quot;0px none #000000&quot; data-ccp-padding-bottom=&quot;0px&quot; data-ccp-border-between=&quot;0px none #000000&quot; data-ccp-padding-between=&quot;0px&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;This role can be based in Waltham, MA or remotely.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Primary Responsibilities Include:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Lead the planning, authoring, review, and completion of clinical and regulatory documents required for submissions to the FDA and other global health authorities&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Manage internal and external medical writing resources to deliver accurate, high-quality documents on time and in accordance with established standards&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Author, edit, and collaborate with cross-functional team members on key documents, including protocols, investigator brochures, clinical study reports, CTD modules, briefing books, and related submission materials&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Review and refine documents or document sections prepared by functional contributors to ensure quality, consistency, scientific accuracy, and adherence to company and regulatory standards&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Contribute to project planning and cross-functional working groups to support efficient development, review, approval, and finalization of submission-ready documents&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Establish and continuously improve medical writing processes, templates, and best practices to increase quality, consistency, and operational efficiency&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Education and Skills Requirements:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Bachelor’s&lt;/span&gt; &lt;span data-contrast=&quot;none&quot;&gt;degree in life sciences or a related discipline required; advanced degree preferred, with a strong understanding of biochemistry and molecular biology principles&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;10+ years of medical writing experience in the pharmaceutical or biotechnology industry, with significant experience preparing clinical and regulatory documents&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;D&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;eep experience authoring and reviewing clinical and regulatory documents&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Ability to lead strategic discussions that align content and messaging across submissions,&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Exceptional communication skills to influence cross-functional stakeholders.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Experience overseeing internal and external medical writing resources, including vendors, consultants, and cross-functional contributors&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Demonstrated expertise writing, editing, and reviewing protocols, clinical study reports, investigator brochures, CTD modules, and other clinical regulatory documents&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Strong understanding of FDA and international regulations, ICH guidelines, and regulatory processes related to document preparation, production, and submission, including CTD requirements&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Experience developing and executing medical writing strategy across programs, submissions, or therapeutic areas&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Proficiency with Microsoft Office, Adobe Acrobat, and shared document management systems such as SharePoint&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Highly organized, with the ability to prioritize, manage multiple projects simultaneously, and deliver high-quality work under tight timelines&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Detailed knowledge of requirements for key clinical, nonclinical, and regulatory documents supporting INDs, CTAs, annual reports, and related submissions&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Strong attention to detail, accuracy, and consistency&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Ability to synthesize, analyze, and present complex clinical and scientific data clearly and accurately&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Self-directed, proactive, and effective at problem solving in a fast-paced, cross-functional environment&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Strong collaboration skills, with the ability to integrate input from multiple contributors into clear, cohesive, submission-ready documents&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
