&lt;p&gt;&lt;strong&gt;Primary Responsibilities Include:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot; data-ccp-parastyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;b669530d-9cee-5fd4-8da3-4cdbed7bfaa2|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[469775450,&amp;quot;Body&amp;quot;,201340122,&amp;quot;2&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;Body&amp;quot;,335572020,&amp;quot;1&amp;quot;,469777841,&amp;quot;Helvetica&amp;quot;,469777842,&amp;quot;Helvetica&amp;quot;,469777843,&amp;quot;Helvetica&amp;quot;,469777844,&amp;quot;Helvetica&amp;quot;,469769226,&amp;quot;Helvetica&amp;quot;,335551500,&amp;quot;0&amp;quot;,268442635,&amp;quot;22&amp;quot;]}&quot;&gt;Strategic Leadership and Evidence Planning&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Serve as the senior Biostatistics lead and subject matter expert for Medical Affairs, providing strategic direction, independent statistical judgment, and hands-on statistical leadership&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Shape integrated evidence-generation strategies and product-level evidence plans in partnership with Medical Affairs, Clinical Development, HEOR, Value &amp;amp; Access, Regulatory, and Commercial stakeholders&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Represent Biostatistics on cross-functional Medical Affairs and evidence-generation teams, influencing strategic decisions and ensuring statistical approaches are scientifically rigorous, practical, and aligned with business and patient needs&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Study Design, Analysis, and Evidence Generation&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Lead statistical strategy, study design, &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;methodology&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;, and execution for Phase IV, observational, registry, and real-world evidence studies&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Lead secondary, exploratory, and post hoc analyses of clinical development data to support Medical Affairs strategy, scientific exchange, publications, congress presentations, payer evidence, and lifecycle planning&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Provide statistical &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;expertise&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt; to HEOR, Value &amp;amp; Access, HTA, and payer-related activities, including methods for evidence generation, interpretation, and communication to external stakeholders&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Provide statistical leadership for clinical outcomes assessment, including PRO/HRQoL analysis, psychometric evaluation, score derivation, endpoint interpretation, and evidence to support publications, payer dossiers, and potential label-enabling activities&lt;/span&gt;&lt;/span&gt; &lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Scientific Communication and Cross-Functional Partnership&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Lead the statistical strategy for Medical Affairs publications and scientific communications, including manuscripts, abstracts, congress presentations, advisory boards, investigator-sponsored research, and external scientific collaborations&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Partner with Clinical Development Biostatistics to &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;leverage&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt; complementary &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;expertise&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;, ensure consistency across the product lifecycle, and &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;maintain&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt; alignment between development, regulatory, and Medical Affairs analyses&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Analyze, interpret, and communicate complex results to cross-functional teams, senior leadership, external collaborators, and non-technical audiences in a clear and actionable manner&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Operational Excellence and Vendor Oversight&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Develop, review, and execute analysis plans, supplemental statistical analysis plans, table/listing/figure shells, dataset specifications, and associated documentation to ensure high-quality, inspection-ready statistical deliverables&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Partner closely with Data Management, Statistical Programming, Clinical Operations, and external vendors to ensure fit-for-purpose data, efficient study execution, and high-quality, &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;timely&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt; statistical deliverables supporting Medical Affairs studies and evidence-generation initiatives&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Provide oversight of CROs, consultants, and external vendors, including scope, quality, timelines, resourcing, issue escalation, and delivery of statistical services&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Functional Leadership and Team Development&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Drive standardization, process improvement, templates, best practices, and functional standards within Biostatistics and across cross-functional teams&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body&quot;&gt;Manage, mentor, and develop direct reports and other statistical colleagues through direct management, matrix leadership, and technical mentorship, fostering technical excellence, collaboration, accountability, and a high-performing team environment&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
